-- Hotel SEO content for the 6 real hotel pages in /stay
-- (Waldorf Astoria Cairo Heliopolis, Sofitel Cairo Downtown Nile,
-- Kempinski Nile Hotel Cairo, Cairo Marriott Hotel & Omar Khayyam Casino,
-- Sofitel Legend Old Cataract Aswan, Movenpick Resort Aswan).
--
-- Every specific fact (room counts, restaurant names, spa details, etc.)
-- was researched and confirmed by the user against real sources (hotel
-- brand sites, Historic Hotels Worldwide, Accor/Kempinski/Marriott
-- listings) before being written in. Anything that stayed unconfirmed is
-- written generally in the article text itself rather than invented, and
-- is not silently dropped here.
--
-- Mapping notes:
--   - full_description holds each hotel's Introduction section (250-280
--     words); article holds the remaining 7 sections (Location & Access
--     through the closing CTA) as HTML with <h2>/<p> tags.
--   - why_we_chose_quote duplicates the "Why We Chose This Hotel" section
--     text as plain descriptive prose (explicitly NOT an attributed quote,
--     per instruction), for the dedicated UI element on the hotel page.
--   - rooms (jsonb) is populated only where a real category/size breakdown
--     was confirmed (Waldorf, Kempinski, Old Cataract, Movenpick); left as
--     an empty array for Sofitel and Cairo Marriott, where it wasn't.
--   - image is NOT NULL in the schema; every row uses the literal
--     'PENDING_UPLOAD' placeholder until real photos are uploaded from the
--     admin panel. gallery/og_image are left NULL/empty until then.
--   - gallery_alt is keyed "1".."25" (not by URL) since there are no real
--     gallery URLs yet -- re-key these to actual image URLs once photos
--     are uploaded, or the alt text won't be picked up by the site.
--   - route/duration are left NULL (Nile-cruise-only fields per schema
--     comments, not applicable to these hotels).
--   - slugs are simplified versions of each hotel name; canonical_url is
--     built from the same slug under /stay/.
--
-- This is a plain INSERT (not an upsert). If a row with one of these
-- slugs already exists, the whole transaction will fail on the unique
-- constraint and roll back cleanly -- tell Claude Code if that happens so
-- this can be switched to an UPDATE instead.
--
-- Run with: psql "$DATABASE_URL" -f content-updates/insert-cairo-aswan-hotels.sql

BEGIN;

-- ============================================================
-- Waldorf Astoria Cairo Heliopolis  (slug: waldorf-astoria-cairo-heliopolis)
-- ============================================================
INSERT INTO hotels (
  name, slug, location, region, type, rating, price_tier, amenities, image, image_alt,
  description, full_description, highlights, gallery, gallery_alt, rooms, facilities, article,
  why_we_chose_quote, route, duration, status, sort_order, focus_keyword, seo_title,
  meta_description, canonical_url, robots, schema_type, og_image, featured, is_partner, partner_logo_url
) VALUES (
  'Waldorf Astoria Cairo Heliopolis', 'waldorf-astoria-cairo-heliopolis', 'Heliopolis, Cairo', 'Cairo', 'Hotel', 5, 'Luxury', ARRAY['Outdoor Pool', 'Waldorf Astoria Spa', '24-Hour Fitness Center', '6 Meeting Rooms + Boardroom', 'Grand Ballroom (1,600 Guests)', 'Business Center', '3 Restaurants & Bars', '10 Minutes from Cairo Airport']::text[], 'PENDING_UPLOAD', NULL,
  'A 252-room Art Deco hotel in Heliopolis blending pharaonic-inspired design with Waldorf Astoria''s classic service, 10 minutes from Cairo International Airport.', 'Waldorf Astoria Cairo Heliopolis brings one of hospitality''s most storied names to one of the city''s most historic districts. Set in Heliopolis, the residential suburb built at the turn of the twentieth century, the hotel houses 252 rooms and suites behind a design language that blends Art Deco proportions with pharaonic motifs — a pairing developed by Adrian Barboza Design that runs from the lobby''s glass-domed ceiling down to the smallest architectural detail. For travelers who want easy airport access without sacrificing a sense of place, the location does double duty: close enough to Cairo International Airport for a short transfer, close enough to downtown for a full day of sightseeing. What follows is a detailed look at the rooms, facilities, dining, and setting that make Waldorf Astoria Cairo Heliopolis one of the properties we recommend most often to guests building a Cairo stay around comfort and design as much as location.', ARRAY['252 Rooms & Suites', '10 Minutes from Cairo International Airport', 'Waldorf Astoria Spa – Psammo Hot-Sand Therapy', '6 Meeting Rooms + Grand Ballroom (1,600 Guests)', '24-Hour Fitness Center', 'Near Baron Empain Palace & Heliopolis Basilica']::text[], ARRAY[]::text[], '{"1":"Glass-domed lobby ceiling at Waldorf Astoria Cairo Heliopolis, inspired by the Eye of Ra","2":"The signature Waldorf Astoria clock surrounded by moving water rings symbolizing the Nile","3":"Art Deco lobby seating area with pharaonic-inspired detailing","4":"Reception desk at Waldorf Astoria Cairo Heliopolis, Heliopolis, Cairo","5":"Lobby lounge blending Art Deco lines with ancient Egyptian motifs","6":"Guest room interior featuring Art Deco and pharaonic-inspired design details","7":"Suite seating area at Waldorf Astoria Cairo Heliopolis","8":"Bedroom with designer furnishings at Waldorf Astoria Cairo Heliopolis","9":"Guest bathroom detailing at Waldorf Astoria Cairo Heliopolis","10":"Suite interior showing the property''s Adrian Barboza design work","11":"Outdoor pool with cabanas at Waldorf Astoria Cairo Heliopolis","12":"Poolside garden seating area","13":"Le Jardin Pool Bar beside the outdoor pool","14":"Cabana seating overlooking the garden pool","15":"Waldorf Astoria Spa treatment room (one of five), Cairo Heliopolis","16":"Hammam interior at the Waldorf Astoria Spa","17":"Psammo hot-sand therapy setup at Waldorf Astoria Spa","18":"Steam room and sauna at the Waldorf Astoria Spa, Cairo Heliopolis","19":"Brasserie Ayda restaurant interior, Mediterranean dining at Waldorf Astoria Cairo Heliopolis","20":"Peacock Lounge jazz bar and afternoon tea setting","21":"Le Jardin Pool Bar outdoor dining area","22":"Exterior facade of Waldorf Astoria Cairo Heliopolis","23":"Grand Ballroom set for an event, Waldorf Astoria Cairo Heliopolis","24":"Business center and event space at Waldorf Astoria Cairo Heliopolis"}'::jsonb, '[{"category":"Deluxe Rooms","count":235},{"category":"Suites","count":17}]'::jsonb, '[{"icon":"spa","label":"Waldorf Astoria Spa – 5 Treatment Rooms, Psammo Hot-Sand Therapy"},{"icon":"pool","label":"Outdoor Pool with Garden Cabanas"},{"icon":"dumbbell","label":"24-Hour Fitness Center (Technogym)"},{"icon":"users","label":"6 Meeting Rooms + Boardroom"},{"icon":"building","label":"Grand Ballroom (1,600 Guests)"},{"icon":"briefcase","label":"Business Center"},{"icon":"utensils","label":"3 Restaurants & Bars"}]'::jsonb, '<h2>Location & Access</h2><p>Heliopolis was laid out in the early 1900s as a planned garden suburb northeast of central Cairo, and it still reads that way today — wider streets, older trees, and a more residential rhythm than the density of downtown or Giza. Waldorf Astoria Cairo Heliopolis sits inside that district, which puts it about 10 minutes from Cairo International Airport, making it a practical first or last stop for a trip built around flight timing. It''s roughly 30 minutes from downtown Cairo by car, depending on traffic, putting the Egyptian Museum, Tahrir Square, and the Nile corniche within reach for a day trip without being on top of them.</p><p>The trade-off is a deliberate one: Heliopolis isn''t the historic core, and it isn''t the Giza Plateau either — it''s a quieter, more residential setting that suits travelers who want to decompress after a flight, or who are using Cairo as a stopover between other parts of Egypt rather than a base for daily sightseeing on foot. For guests planning to see the Pyramids, Egyptian Museum, or Islamic Cairo, a private driver or transfer is the practical way to reach them, and the hotel''s own airport proximity means the return leg at the end of a trip is short and low-stress.</p><h2>Rooms & Suites</h2><p>Across 252 rooms and suites, Waldorf Astoria Cairo Heliopolis breaks down into 235 Deluxe Rooms, each configured with either a king bed or twin beds, and 17 suites at the top of the property''s room hierarchy. The design signature — Art Deco lines paired with pharaonic-inspired detailing, developed throughout by Adrian Barboza Design — runs from the public spaces into these rooms, carrying the same geometric-meets-ancient-Egyptian language guests encounter in the lobby.</p><p>The split between 235 Deluxe Rooms and 17 suites tells its own story about the property: this is a hotel built primarily around a strong, consistent standard room product, with a comparatively small, more exclusive suite tier rather than a wide ladder of intermediate categories. For guests choosing between the two, the practical difference is scale and configuration — Deluxe Rooms offer the flexibility of king or twin bedding, suiting both couples and travelers sharing a room, while the 17 suites represent the top of what the hotel offers.</p><p>Specific suite names, exact square footage, and view configurations by category still aren''t confirmed — these should be verified directly from the hotel''s current room descriptions rather than assumed.</p><h2>Facilities & Services</h2><p>The Waldorf Astoria Spa is built around Psammo therapy, a hot-sand treatment drawing on a documented ancient Egyptian therapeutic tradition. The spa includes a hammam, a steam room, and a sauna, spread across five treatment rooms — a genuinely well-equipped facility for a hotel of this size, not just a token wellness offering attached to the gym.</p><p>Fitness facilities run on a 24-hour basis, equipped with Technogym machines. Outdoors, the pool area is set within a garden and includes cabanas, giving it a resort feel despite the hotel''s urban, airport-adjacent setting.</p><p>For events, the property''s infrastructure runs to six meeting rooms plus a separate boardroom, alongside the Grand Ballroom''s 1,600-guest capacity and the on-site business center — a genuinely substantial events infrastructure, positioning this hotel as a serious option for conferences and large weddings alongside its leisure appeal.</p><p>Select stays include access to the Rosetta Club lounge — the exact eligibility criteria weren''t confirmed, so this should be stated precisely rather than left vague once verified.</p><p>Across the property, the design signature repeats: the lobby''s glass dome is built around an "Eye of Ra" motif, and the hotel''s Waldorf Astoria clock sits at the center of moving rings of water, a direct visual reference to the Nile.</p><h2>Dining</h2><p>Three food and beverage venues cover a reasonably wide range of occasions. Brasserie Ayda serves Mediterranean cuisine and appears to function as the hotel''s main restaurant, based on its positioning. Peacock Lounge is built around a jazz bar concept and also hosts afternoon tea, giving it a dual role — an evening drinks destination and a daytime tea-service venue in one space. Le Jardin Pool Bar serves the outdoor pool and garden area, the natural spot for a daytime drink or light bite between the pool and the cabanas described earlier.</p><p>Together, the three venues give the hotel a solid on-site dining program — informal poolside, a signature restaurant, and a lounge with its own afternoon-tea identity — without needing to send guests off-property for every meal. Guests looking for more variety have that option close by too: Bar Raa, an independent restaurant roughly five minutes'' walk from the hotel, though as a separate business it falls outside what the hotel itself offers.</p><h2>Why We Chose This Hotel</h2><p>We selected Waldorf Astoria Cairo Heliopolis for iLuxury Egypt packages because it delivers a genuinely different kind of Cairo stay than the downtown and Giza properties most itineraries default to. Its Heliopolis setting offers a quieter, more residential backdrop while still keeping the airport close — a practical advantage for the first and last nights of a longer Egypt itinerary, when guests are managing flight logistics rather than sightseeing.</p><p>The scale of the property, at 252 rooms with a 1,600-capacity ballroom and six meeting rooms plus a boardroom, makes it equally suited to a couple''s stay or a larger group traveling together. And the design work throughout — the Adrian Barboza Art Deco and pharaonic pairing, the Eye of Ra dome, the Nile-referencing water rings around the branded clock — gives the property a sense of place that a purely international-standard luxury hotel wouldn''t have.</p><p>Combined with a spa built around an authentically Egyptian treatment tradition rather than an imported one, Waldorf Astoria Cairo Heliopolis fits naturally into itineraries where we want every stop, including the hotel itself, to say something specific about Egypt.</p><h2>Nearby Attractions & Activities</h2><p>Heliopolis itself is worth a slow look before heading further into Cairo. Two landmarks confirm the district''s architectural character: Baron Empain Palace, the early-1900s residence built by the Belgian industrialist who founded Heliopolis, styled after Cambodia''s Angkor Wat; and the Heliopolis Basilica, a church whose design draws on Istanbul''s Hagia Sophia. Both sit within the district around the hotel.</p><p>Cairo''s headline sights remain a drive away: downtown Cairo, with the Egyptian Museum and Tahrir Square, is roughly 30 minutes by car, while the Giza Plateau — home to the Pyramids and the Great Sphinx — sits about 22 miles (roughly 35 kilometers) from the hotel, confirming it as a longer excursion best arranged with a private driver.</p><p>For guests with a short layover or a single free day, exploring Heliopolis''s own landmarks first, then arranging a driver for Giza or downtown, is the most efficient way to use limited time.</p><h2>Plan Your Stay</h2><p>Waldorf Astoria Cairo Heliopolis suits travelers who want a Cairo stay built on design, scale, and airport convenience — whether that''s the opening night of an Egypt itinerary, the closing night before an early flight, or a base for a Cairo-focused trip that values a quieter residential setting over a downtown address. With iLuxury Egypt, a stay here can be arranged as a standalone booking or folded into a full itinerary alongside Luxor, Aswan, and the Nile — with private transfers, a dedicated Egyptologist guide, and every other detail of your trip handled around it. Get in touch with our team to check availability and start planning your stay.</p>',
  'We selected Waldorf Astoria Cairo Heliopolis for iLuxury Egypt packages because it delivers a genuinely different kind of Cairo stay than the downtown and Giza properties most itineraries default to. Its Heliopolis setting offers a quieter, more residential backdrop while still keeping the airport close — a practical advantage for the first and last nights of a longer Egypt itinerary, when guests are managing flight logistics rather than sightseeing. The scale of the property, at 252 rooms with a 1,600-capacity ballroom and six meeting rooms plus a boardroom, makes it equally suited to a couple''s stay or a larger group traveling together. And the design work throughout — the Adrian Barboza Art Deco and pharaonic pairing, the Eye of Ra dome, the Nile-referencing water rings around the branded clock — gives the property a sense of place that a purely international-standard luxury hotel wouldn''t have. Combined with a spa built around an authentically Egyptian treatment tradition rather than an imported one, Waldorf Astoria Cairo Heliopolis fits naturally into itineraries where we want every stop, including the hotel itself, to say something specific about Egypt.', NULL, NULL, 'published', 0, 'waldorf astoria cairo heliopolis', 'Waldorf Astoria Cairo Heliopolis | Luxury Hotel Review',
  'Waldorf Astoria Cairo Heliopolis: 252 rooms, Art Deco design, 10 minutes from Cairo Airport. Full guide to rooms, spa, dining, and location.', 'https://iluxuryegypt.com/stay/waldorf-astoria-cairo-heliopolis', 'index, follow', 'Hotel', NULL, false, false, NULL
);

