-- Sofitel Cairo Downtown Nile  (slug: sofitel-cairo-downtown-nile)
-- ============================================================
INSERT INTO hotels (
  name, slug, location, region, type, rating, price_tier, amenities, image, image_alt,
  description, full_description, highlights, gallery, gallery_alt, rooms, facilities, article,
  why_we_chose_quote, route, duration, status, sort_order, focus_keyword, seo_title,
  meta_description, canonical_url, robots, schema_type, og_image, featured, is_partner, partner_logo_url
) VALUES (
  'Sofitel Cairo Downtown Nile', 'sofitel-cairo-downtown-nile', '1191 Nile Corniche, Downtown Cairo', 'Cairo', 'Hotel', 5, 'Luxury', ARRAY['Sofitel Spa (1,000 sqm)', 'Outdoor Pool (300 sqm)', 'Sofitel Fitness (Technogym)', '18 Event Venues', 'Club Millésime Lounge (22nd Floor)', '4 Restaurants & 2 Bars', '24-Hour Butler Service (Suites)']::text[], 'PENDING_UPLOAD', NULL,
  'A 615-room riverside hotel in downtown Cairo blending French "Art de Vivre" elegance with Egyptian character, set directly on the Nile Corniche.', 'Sofitel Cairo Downtown Nile occupies one of the more central riverside addresses in the capital, part of the Sofitel brand''s global positioning around French-inflected luxury — the "Art de Vivre" philosophy that runs across every Sofitel property, blending local character with a consistently French sensibility in service and design. Set in downtown Cairo along the Nile, the hotel puts guests within walking distance of the city''s historic core rather than in the more residential or suburban settings some Cairo luxury hotels occupy. What follows covers the location, rooms, facilities, and dining that define a stay here.', ARRAY['615 Rooms & Suites Across 24 Floors', 'Every Room Has a Private Balcony', '1,000 sqm Sofitel Spa', '300 sqm Outdoor Pool', '18 Event Venues', 'Club Millésime – 22nd Floor']::text[], ARRAY[]::text[], '{"1":"Sofitel Cairo Downtown Nile exterior facade, Nile Corniche","2":"Sofitel Cairo Downtown Nile lobby interior","3":"Sofitel Cairo Downtown Nile guest room with Nile view","4":"Sofitel Cairo Downtown Nile suite living area","5":"Sofitel Cairo Downtown Nile guest room private balcony","6":"Sofitel Cairo Downtown Nile Club Millésime lounge, 22nd floor","7":"Sofitel Cairo Downtown Nile spa-style bathroom with rainfall shower","8":"Sofitel Spa treatment room, Cairo Downtown Nile","9":"Sofitel Spa jacuzzi area","10":"Sofitel Cairo Downtown Nile outdoor pool, 300 sqm","11":"Sofitel Cairo Downtown Nile poolside cabana seating","12":"Sofitel Fitness gym overlooking the pool","13":"Jayda Nile Terrace restaurant, Egyptian-Lebanese dining","14":"Kamala restaurant interior, East Asian cuisine","15":"Stage One Bar, Sofitel Cairo Downtown Nile","16":"Sofitel Cairo Downtown Nile Pool Bar","17":"Sofitel Cairo Downtown Nile event venue set for a conference","18":"Sofitel Cairo Downtown Nile ballroom set for a wedding","19":"Sofitel Cairo Downtown Nile Nile-view dining terrace at sunset","20":"Sofitel Cairo Downtown Nile reception desk","21":"Sofitel Cairo Downtown Nile corridor, French-inspired interior design","22":"Sofitel Cairo Downtown Nile skyline view from a guest room","23":"Sofitel Cairo Downtown Nile evening exterior lighting","24":"Sofitel Cairo Downtown Nile Nile Corniche walkway view","25":"Sofitel Cairo Downtown Nile rooftop view over central Cairo"}'::jsonb, '[]'::jsonb, '[{"icon":"spa","label":"Sofitel Spa – 1,000 sqm, Jacuzzi & Separate Male/Female Saunas"},{"icon":"pool","label":"Outdoor Pool – 300 sqm with Private Cabanas"},{"icon":"dumbbell","label":"Sofitel Fitness – Technogym Equipment"},{"icon":"users","label":"18 Event Venues"},{"icon":"star","label":"Club Millésime – 22nd-Floor Lounge Tier"},{"icon":"utensils","label":"4 Restaurants & 2 Bars"}]'::jsonb, '<h2>Location & Access</h2><p>The hotel sits at 1191 Nile Corniche, Souq Al Asr Bulaq — directly on the Nile in downtown Cairo. This central location puts the Egyptian Museum in Tahrir Square, and the Nile corniche within easy reach, with the Egyptian Museum reachable on foot along the corniche or via a short taxi ride, and the Great Pyramid of Giza roughly a 30-minute taxi ride away. Khan el-Khalili bazaar is also within reach for a half-day exploring Cairo''s history and shopping.</p><p>Downtown Cairo itself is the historic, commercial heart of the modern city — a different character from Giza''s desert-edge sprawl or Heliopolis''s garden-suburb quiet, with denser streets and closer proximity to the city''s museums and government buildings.</p><h2>Rooms & Suites</h2><p>Across 24 floors, the hotel offers 615 guestrooms and suites, each with a private balcony — a rare feature at this scale in central Cairo. Interiors layer French elegance with vibrant local touches, while spa-style bathrooms with rainfall showers and luxury amenities add a sense of sanctuary. Suites feature separate living areas, panoramic Nile views, and 24-hour butler service. The hotel also includes Club Millésime, an elevated accommodation and lounge tier on the 22nd floor.</p><p>A confirmed breakdown of the 615 rooms and suites by specific category, and further detail on Club Millésime''s own room configuration, are not yet confirmed and should be checked against the hotel''s current site before publishing specific category names or counts.</p><h2>Facilities & Services</h2><p>Sofitel Spa spans 1,000 square metres, blending French beauty traditions with Egyptian influences — guests can unwind in a Jacuzzi, and separate male and female saunas. The outdoor pool covers 300 square metres, framed by private cabanas with direct pool access. Sofitel Fitness offers cutting-edge Technogym equipment overlooking the outdoor pool. For events, the property offers 18 event venues — a substantial capacity that positions this hotel among Cairo''s leading venues for weddings and conferences.</p><h2>Dining</h2><p>Dining spans four main restaurants and two bars. Jayda Nile Terrace serves Egyptian-Lebanese plates with Nile views. Kamala offers refined East Asian cuisine. Stage One combines cocktails and nightlife in a lively bar setting, with a separate Stage One Bar and Pool Bar rounding out the drinks offering. Together, these venues give the hotel a genuinely international dining program anchored by its riverside setting.</p><p>The exact name and cuisine of a possible fourth distinct restaurant venue beyond Jayda Nile Terrace and Kamala is not fully confirmed and should be verified against the hotel''s current site before publishing further specifics.</p><h2>Why We Chose This Hotel</h2><p>We selected Sofitel Cairo Downtown Nile for its combination of scale, location, and the distinctly French sensibility that sets it apart from Cairo''s other international hotels. With 615 rooms and suites, all with private balconies over the Nile, and 18 event spaces, this hotel accommodates everything from a couple''s stay to a large-scale conference without losing its sense of place — a genuine blend of Egyptian heritage and French elegance in the heart of the capital.</p><h2>Nearby Attractions & Activities</h2><p>Steps from the hotel, the Nile Corniche offers an evening walking route past Egypt Walkway, where a platform extends over the river itself. The Egyptian Museum is reachable on foot or by a short taxi ride along the corniche. Khan el-Khalili bazaar combines historic shopping with Cairo''s older architecture, and the Great Pyramid of Giza is roughly a 30-minute taxi ride for a half-day or full-day excursion.</p><h2>Plan Your Stay</h2><p>Sofitel Cairo Downtown Nile suits travelers who want to be in the heart of Cairo, on the Nile itself, with the scale and event infrastructure of a major international hotel. With iLuxury Egypt, a stay here can be arranged standalone or as part of a full Egypt itinerary. Get in touch with our team to check availability and start planning your stay.</p>',
  'We selected Sofitel Cairo Downtown Nile for its combination of scale, location, and the distinctly French sensibility that sets it apart from Cairo''s other international hotels. With 615 rooms and suites, all with private balconies over the Nile, and 18 event spaces, this hotel accommodates everything from a couple''s stay to a large-scale conference without losing its sense of place — a genuine blend of Egyptian heritage and French elegance in the heart of the capital.', NULL, NULL, 'published', 1, 'sofitel cairo downtown nile', 'Sofitel Cairo Downtown Nile | Luxury Hotel on the Nile',
  'Sofitel Cairo Downtown Nile: 615 rooms with private balconies, a 1,000 sqm spa, and four restaurants on the Nile Corniche in central Cairo.', 'https://iluxuryegypt.com/stay/sofitel-cairo-downtown-nile', 'index, follow', 'Hotel', NULL, false, false, NULL
);

