-- Sofitel Legend Old Cataract Aswan  (slug: old-cataract-aswan)
-- ============================================================
INSERT INTO hotels (
  name, slug, location, region, type, rating, price_tier, amenities, image, image_alt,
  description, full_description, highlights, gallery, gallery_alt, rooms, facilities, article,
  why_we_chose_quote, route, duration, status, sort_order, focus_keyword, seo_title,
  meta_description, canonical_url, robots, schema_type, og_image, featured, is_partner, partner_logo_url
) VALUES (
  'Sofitel Legend Old Cataract Aswan', 'old-cataract-aswan', 'Nile Corniche, Aswan', 'Aswan', 'Hotel', 5, 'Luxury', ARRAY['So SPA (Hammam, Jacuzzi, Heated Indoor Pool)', 'Olympic-Size Outdoor Pool', '1902 Restaurant', 'Agatha Christie Suite & Sir Winston Churchill Suite', 'Kids Club', 'Nile Terrace Views']::text[], 'PENDING_UPLOAD', NULL,
  'The 1899 Nile-side hotel famed for its Agatha Christie history, Moorish architecture, and panoramic terraces over Elephantine Island in Aswan.', 'Few hotels in Egypt carry the literary and historical weight of the Sofitel Legend Old Cataract Aswan. Built in 1899 by Thomas Cook on a granite outcrop above the Nile''s First Cataract, the hotel''s distinctive pink Moorish-Victorian façade has watched over Aswan for well over a century, overlooking Elephantine Island and the river''s granite boulders from a position no other hotel in the city shares. It is best known today for its association with Agatha Christie, who stayed at the property and drew on it while writing Death on the Nile — the hotel''s terrace and dining rooms have carried that literary reputation ever since, reinforced by the building''s appearance in the 1978 film adaptation.

The guest list over the twentieth century reads like a history of the region: Winston Churchill stayed here, as did Howard Carter during his years excavating in the Valley of the Kings, and Aga Khan III, whose domed mausoleum stands on the Nile''s west bank directly across from the hotel. That density of history is part of why the Old Cataract remains one of the most recognized hotel names in Egypt, distinct even from other grand historic properties on the Nile.

The hotel underwent a major, multi-year restoration before reopening under the Sofitel Legend brand, preserving its original architecture and decorative detail while updating the building for contemporary luxury standards. This guide covers its rooms, dining, facilities, and setting on the Nile in Aswan, along with what remains unconfirmed and worth checking before publishing specific claims.', ARRAY['Built in 1899 Above the Nile''s First Cataract', '220 Rooms & Suites Across the Palace and Nile Wing', 'Agatha Christie Suite & Sir Winston Churchill Suite', 'So SPA with Hammam & Heated Indoor Pool', '1902 Restaurant Beneath a Historic Dome', 'View of the Aga Khan Mausoleum']::text[], ARRAY[]::text[], '{"1":"Old Cataract Aswan hotel exterior, pink Moorish facade","2":"Old Cataract Aswan terrace overlooking the Nile","3":"Old Cataract Aswan view of Elephantine Island","4":"Old Cataract Aswan Palace building guest room","5":"Old Cataract Aswan Nile Wing guest room","6":"Old Cataract Aswan Agatha Christie Suite living area","7":"Old Cataract Aswan Sir Winston Churchill Suite","8":"Old Cataract Aswan 1902 Restaurant domed interior","9":"Old Cataract Aswan Palms restaurant, poolside dining","10":"Old Cataract Aswan sunset view from the terrace","11":"Old Cataract Aswan Olympic-size swimming pool","12":"Old Cataract Aswan So SPA hammam interior","13":"Old Cataract Aswan So SPA heated indoor pool","14":"Old Cataract Aswan garden grounds above the Nile","15":"Old Cataract Aswan lobby, historic interior detail","16":"Old Cataract Aswan suite with Nile view","17":"Old Cataract Aswan view of the Aga Khan Mausoleum","18":"Old Cataract Aswan granite boulders, First Cataract view","19":"Old Cataract Aswan hallway, Moorish architectural detail","20":"Old Cataract Aswan felucca dock access","21":"Old Cataract Aswan afternoon tea on the terrace","22":"Old Cataract Aswan aerial view of the hotel and river","23":"Old Cataract Aswan domed ceiling detail","24":"Old Cataract Aswan pool deck seating area","25":"Old Cataract Aswan facade at dusk"}'::jsonb, '[{"category":"Palace Building (approx.)","count":76,"notes":"including approx. 45 suites"},{"category":"Nile Wing (approx.)","count":62,"notes":"including approx. 37 suites"},{"category":"Total","count":220}]'::jsonb, '[{"icon":"spa","label":"So SPA – Hammam, Jacuzzi, Heated Adults-Only Indoor Pool"},{"icon":"pool","label":"Olympic-Size Outdoor Pool with Private Cabanas"},{"icon":"users","label":"Kids Club with Activities & Childcare"},{"icon":"briefcase","label":"Car Rental, Currency Exchange & Laundry"},{"icon":"compass","label":"Sunset Felucca & Breakfast Cruise Booking"}]'::jsonb, '<h2>Location & Access</h2><p>The hotel sits on the east bank of the Nile in Aswan, on raised ground that gives most of the property clear views over the river, Elephantine Island, and the granite boulders of the First Cataract — the section of the Nile that historically marked Egypt''s southern frontier. This elevated, riverside position is part of what has made the hotel a landmark visible from much of Aswan''s waterfront.</p><p>Aswan itself is a notably compact, walkable city compared with Cairo or Luxor, and the hotel''s location near the corniche puts the Nubian Museum, the Aswan souk, and the felucca docks for Elephantine Island and Kitchener''s Island within easy reach — generally a short walk or a brief taxi ride rather than a long transfer.</p><p>Aswan International Airport is a drive of roughly 25–30 minutes from central Aswan, though exact timing depends on traffic and the specific route. A confirmed figure for the hotel''s own airport-transfer policy is not yet available and should be checked against the hotel''s current site before publishing a specific claim.</p><p>For travelers combining Aswan with Abu Simbel, the temples are typically reached by a longer road transfer (around three hours each way) or a short domestic flight; the hotel''s central Aswan location doesn''t materially change those logistics, but it does make it a convenient base for arranging Nile-boat excursions to Philae Temple, the High Dam, and the unfinished obelisk, all of which sit within a short drive of the property.</p><h2>Rooms & Suites</h2><p>The Old Cataract holds 220 rooms and suites in total, split between the original 1899 Palace building and the later Nile Wing. Confirmed research puts roughly 76 rooms and suites (including 45 suites) in the Palace building, and approximately 62 rooms and suites (including 37 suites) in the Nile Wing — sources vary slightly on the exact Nile Wing figure, so the 220 total is the reliable number and the building-by-building split is approximate pending a final check against the hotel''s own current listing.</p><p>Rooms in the historic Palace building carry the property''s original character — higher ceilings, Moorish architectural detailing, and in many cases direct views over the Nile and Elephantine Island — while Nile Wing rooms are more contemporary in style, still designed to complement the hotel''s overall aesthetic but built to a more standard modern layout.</p><p>Signature suites here are genuinely named after the hotel''s most famous guests, not a marketing invention: the Agatha Christie Suite is a real, currently offered suite, with a king bedroom, separate living and dining areas, and a private balcony overlooking the Nile. The hotel also offers a Sir Winston Churchill Suite at the same level. Guests specifically seeking the hotel''s storied character should book into the Palace building — and, budget allowing, one of these two named suites — rather than assume any Old Cataract room delivers that atmosphere, since the Nile Wing remains a more conventional modern-hotel product by comparison.</p><h2>Facilities & Services</h2><p>The hotel''s spa, So SPA (part of Sofitel''s global So SPA brand), includes a hammam, a jacuzzi, and a heated indoor pool reserved for adults only, set beneath mosaic-tiled columns that echo the property''s Moorish architecture. A confirmed treatment-room count or full treatment menu for this specific property is not yet available.</p><p>Outdoors, the hotel has an Olympic-size swimming pool set within its riverside grounds, ringed by private cabanas — a scale of pool unusual for a historic hotel of this era, reflecting later expansion of the property''s leisure facilities.</p><p>For families, the hotel runs a Kids Club with organized activities and childcare, and guest services include car rental, currency exchange, laundry, and an on-site desk for booking Nile excursions — sunset felucca sails and breakfast cruises are specifically arranged through the hotel, taking advantage of its direct riverbank access.</p><p>Meeting-room count, maximum event capacity, and full gym specifications remain unconfirmed and should be checked against the hotel''s current site before publishing specific numbers.</p><h2>Dining</h2><p>Dining research confirms four restaurants and bars on the property, with two names verified with confidence.</p><p>1902 Restaurant is the hotel''s grand, domed historic dining room, serving gourmet nouvelle French cuisine with dedicated sommelier wine service, beneath the same Moorish-style dome that has made the room one of the most photographed restaurant interiors in Egypt.</p><p>Palms is a poolside restaurant serving international cuisine, positioned for casual dining by the Olympic-size pool rather than the formal historic setting of 1902 Restaurant.</p><p>Sources reference a total of four dining venues, with at least one additional restaurant reportedly focused on Middle Eastern/Oriental cuisine — a confirmed name for it or for the fourth venue is not yet available, so specifics are not stated here until verified against the hotel''s own current site.</p><p>The hotel''s Nile-view terrace remains part of the dining and drinks experience separately from these named restaurants, and continues to carry the property''s Agatha Christie association.</p><h2>Why We Chose This Hotel</h2><p>Some hotels are chosen for their rooms. The Old Cataract is chosen for what happened in them. This is the hotel where Agatha Christie drew inspiration for Death on the Nile, where Winston Churchill stayed, where Howard Carter returned after his seasons in the Valley of the Kings, and where the domed mausoleum of Aga Khan III, visible from the terrace across the river, is a permanent reminder of how deeply this property is woven into the history of modern Aswan.</p><p>Built in 1899 on granite above the First Cataract, the hotel''s pink Moorish façade has remained one of the most photographed buildings in southern Egypt for well over a century, and its careful restoration under the Sofitel Legend brand kept that architecture intact rather than replacing it with something more generically modern. For travelers who want a Nile stay that comes with a genuine sense of place — not just a river view, but a documented, century-long relationship with the writers, explorers, and heads of state who have watched the same sunset from the same terrace — the Old Cataract offers something very few hotels anywhere can claim: it is not merely near the history of Aswan, it is part of it.</p><h2>Nearby Attractions & Activities</h2><p>Aswan''s major sites sit unusually close together, and the Old Cataract''s central, riverside position makes most of them a short excursion away rather than a full transfer. Elephantine Island, directly opposite the hotel, is reachable by a brief felucca crossing and holds the Nubian villages and the Aswan Museum among its ancient ruins. Kitchener''s Island, known for its botanical gardens, sits just beyond it and is a common pairing for the same short boat trip.</p><p>The Aga Khan Mausoleum, visible from the hotel''s own terrace on the Nile''s west bank, is a short boat ride away and directly tied to the hotel''s own history through Aga Khan III''s association with the property. Philae Temple, dedicated to Isis and relocated to Agilkia Island during the Nile rescue campaigns of the 1970s, is a short drive followed by a boat crossing, and the Aswan High Dam and the unfinished obelisk in the ancient granite quarries are both within a similarly short drive of the hotel.</p><p>The Nubian Museum and Aswan''s souk, both within the compact central city, are close enough for a walk or brief taxi ride from the hotel, making an afternoon of museum-going and market browsing an easy addition without arranging transport in advance.</p><p>For travelers extending further south, Abu Simbel is typically reached by a longer road transfer or a short flight; the Old Cataract''s location doesn''t shorten that trip, but it makes an ideal base the nights before and after.</p><h2>Plan Your Stay</h2><p>The Sofitel Legend Old Cataract Aswan is not simply a luxury hotel with a Nile view — it is a documented piece of Egypt''s modern history, the setting for one of literature''s best-known Nile mysteries and the resting place, in view from its own terrace, of one of the twentieth century''s most significant spiritual leaders. For travelers who want their Aswan stay to carry that same weight of place, few hotels anywhere on the Nile can offer it. Get in touch with our team to check availability and start planning your stay.</p>',
  'Some hotels are chosen for their rooms. The Old Cataract is chosen for what happened in them. This is the hotel where Agatha Christie drew inspiration for Death on the Nile, where Winston Churchill stayed, where Howard Carter returned after his seasons in the Valley of the Kings, and where the domed mausoleum of Aga Khan III, visible from the terrace across the river, is a permanent reminder of how deeply this property is woven into the history of modern Aswan. Built in 1899 on granite above the First Cataract, the hotel''s pink Moorish façade has remained one of the most photographed buildings in southern Egypt for well over a century, and its careful restoration under the Sofitel Legend brand kept that architecture intact rather than replacing it with something more generically modern. For travelers who want a Nile stay that comes with a genuine sense of place — not just a river view, but a documented, century-long relationship with the writers, explorers, and heads of state who have watched the same sunset from the same terrace — the Old Cataract offers something very few hotels anywhere can claim: it is not merely near the history of Aswan, it is part of it.', NULL, NULL, 'published', 4, 'old cataract aswan', 'Sofitel Legend Old Cataract Aswan | Historic Nile Hotel',
  'Stay at the Sofitel Legend Old Cataract Aswan, the 1899 Nile-side hotel famed for its Agatha Christie history, Moorish architecture, and panoramic terraces over Elephantine Island.', 'https://iluxuryegypt.com/stay/old-cataract-aswan', 'index, follow', 'Hotel', NULL, false, false, NULL
);

