-- Mövenpick Resort Aswan  (slug: movenpick-aswan)
-- ============================================================
INSERT INTO hotels (
  name, slug, location, region, type, rating, price_tier, amenities, image, image_alt,
  description, full_description, highlights, gallery, gallery_alt, rooms, facilities, article,
  why_we_chose_quote, route, duration, status, sort_order, focus_keyword, seo_title,
  meta_description, canonical_url, robots, schema_type, og_image, featured, is_partner, partner_logo_url
) VALUES (
  'Mövenpick Resort Aswan', 'movenpick-aswan', 'Elephantine Island, Aswan', 'Aswan', 'Resort', 5, 'Luxury', ARRAY['24-Hour Complimentary Boat Transfer (~5 Minutes)', 'Two Outdoor Pools + Indoor Jacuzzi', 'Spa & Fully Equipped Gym', '4 Restaurants + 3 Bars', '800+ sqm Meeting Space', 'Organic Farm, Deer Farm & Bird-Watching Station']::text[], 'PENDING_UPLOAD', NULL,
  'A 404-room resort occupying the southern tip of Elephantine Island in the Nile, reached by a complimentary 24-hour boat transfer from central Aswan.', 'The Mövenpick Resort Aswan occupies one of the most distinctive settings of any hotel on the Nile: the entirety of Elephantine Island''s southern tip, an islet in the middle of the river directly opposite central Aswan. Where the Old Cataract looks out at the island from the east bank, the Mövenpick sits inside that view — surrounded by the Nile on nearly every side, with the ancient ruins, Nubian villages, and the Aswan Museum sharing the same island a short walk to the north.

That island setting shapes the entire stay here. Guests reach the mainland by a short boat crossing included as part of the hotel''s own transfer service, and once on the island, the resort''s tower and gardens are positioned to take in views of the river, the granite hills of the west bank, and central Aswan''s skyline from nearly every angle. It is a genuinely different proposition from a riverside hotel on the mainland — closer, in feel, to a private island resort than to a conventional city-adjacent property, despite sitting only a few minutes by boat from downtown Aswan.

Originally opened in 1976, renovated in 2008, and expanded with the Elephantine Extension wing in 2016, the resort blends an established island layout with more recently built accommodation. This guide covers its rooms, dining, facilities, and island setting, along with what remains unconfirmed and worth checking before publishing specific claims.', ARRAY['404 Rooms, Suites & Villas Across Two Wings', 'Every Room Has a Private Balcony or Terrace', '24-Hour Complimentary Boat Transfer (~5 Minutes)', '147 sqm Presidential Suite with Private Jacuzzi', '4 Restaurants Including Panorama, Highest in the City', '3,000+ Fruit Trees, Organic Farm & Deer Farm']::text[], ARRAY[]::text[], '{"1":"Mövenpick Resort Aswan exterior, Elephantine Island","2":"Mövenpick Resort Aswan aerial view, Nile island setting","3":"Mövenpick Resort Aswan guest room with Nile view","4":"Mövenpick Resort Aswan tower building on the Nile","5":"Mövenpick Resort Aswan Presidential Suite with private jacuzzi","6":"Mövenpick Resort Aswan family villa exterior","7":"Mövenpick Resort Aswan outdoor swimming pool","8":"Mövenpick Resort Aswan indoor jacuzzi","9":"Mövenpick Resort Aswan garden grounds, island setting","10":"Mövenpick Resort Aswan boat dock, island transfer","11":"Mövenpick Resort Aswan sunset view over the Nile","12":"Mövenpick Resort Aswan lobby interior","13":"Mezze Restaurant, Egyptian and Nubian cuisine","14":"Panorama Restaurant & Bar, 360-degree tower views","15":"Al Qahwa bar and lounge, fresh fruit cocktails","16":"Orangerie glass-fronted restaurant","17":"Mövenpick Resort Aswan view of Aswan corniche from the island","18":"Mövenpick Resort Aswan meeting room with floor-to-ceiling windows","19":"Mövenpick Resort Aswan organic farm and fruit orchards","20":"Mövenpick Resort Aswan deer farm","21":"Mövenpick Resort Aswan bird-watching station","22":"Mövenpick Resort Aswan view toward the west bank granite hills","23":"Mövenpick Resort Aswan evening lighting, island resort","24":"Mövenpick Resort Aswan poolside seating area","25":"Mövenpick Resort Aswan panoramic Nile view from a guest balcony"}'::jsonb, '[{"category":"Classic Twin (example)","size":"32 sqm"},{"category":"Higher-Category Room (example)","size":"38 sqm"},{"category":"Family Villa","size":"110 sqm"},{"category":"Presidential Suite","size":"147 sqm","notes":"Two bedrooms, private outdoor jacuzzi"},{"category":"Total Rooms, Suites & Villas","count":404}]'::jsonb, '[{"icon":"ship","label":"24-Hour Complimentary Boat Transfer (~5 Minutes to Mainland)"},{"icon":"pool","label":"Two Outdoor Pools + Indoor Jacuzzi"},{"icon":"spa","label":"Spa (Treatment Rooms, Steam Room & Sauna)"},{"icon":"dumbbell","label":"Fully Equipped Gym"},{"icon":"users","label":"800+ sqm Meeting Space with Floor-to-Ceiling Windows"},{"icon":"leaf","label":"3,000+ Fruit Trees, Organic Farm, Deer Farm & Bird-Watching Station"},{"icon":"utensils","label":"4 Restaurants + 3 Bars"}]'::jsonb, '<h2>Location & Access</h2><p>The hotel occupies the southern end of Elephantine Island, in the middle of the Nile directly across from Aswan''s corniche and city center. Access is by boat: the hotel operates a complimentary transfer service running 24 hours a day, with the crossing itself taking around five minutes — meaning guests can move between the island and the mainland at any hour without needing to plan around a fixed schedule.</p><p>This island position keeps the hotel practically as close to central Aswan as any mainland property — Aswan railway station is about 5 minutes from the mainland dock, and Aswan International Airport is roughly 20 minutes away. Elephantine Island itself, sharing part of its grounds with the hotel, holds ancient ruins and Nubian villages within walking distance of the resort.</p><p>The Nubian Museum, the Aswan souk, and the corniche are all a short boat crossing plus a brief walk from the hotel, combining island seclusion with genuinely fast access to the city center.</p><h2>Rooms & Suites</h2><p>The resort holds 404 rooms, suites, and villas in total, split across two wings, all with a private balcony or terrace. Room sizes range from 32-square-metre Classic Twin rooms up to more spacious higher-category rooms around 38 square metres, with family villas reaching 110 square metres for guests wanting more space.</p><p>The resort''s Presidential Suite is its top accommodation tier: 147 square metres with two bedrooms and a private outdoor jacuzzi, positioned as the flagship suite for guests wanting the most space and privacy the property offers.</p><p>The hotel underwent a full renovation in 2008, with an additional wing — the Elephantine Extension — added in 2016, meaning the accommodation blends an established resort layout with a more recently built wing. A confirmed split of how many of the 404 rooms fall into each specific category is not yet available — the sizes above are representative examples rather than a full category breakdown, and a complete room-type list should be checked against the hotel''s current site before publishing category names as fixed.</p><p>Given every room includes a private balcony or terrace, and the resort sits on an island surrounded by the Nile, a high proportion of rooms likely carry some form of water or island view by default, though which specific rooms face the river directly versus the island''s interior gardens is still worth confirming.</p><h2>Facilities & Services</h2><p>The resort has two outdoor swimming pools and an indoor jacuzzi, giving guests more pool options than most Aswan hotels on the mainland. A spa is confirmed on-site, with treatment rooms and both a steam room and sauna, alongside a fully equipped gym — a confirmed spa name and full treatment menu are not yet available for this property.</p><p>Meeting and event space totals more than 800 square metres, arranged as flexible rooms with floor-to-ceiling windows bringing in natural light — a genuinely substantial events capacity for a resort in Aswan, though the exact number of individual meeting rooms remains unconfirmed.</p><p>The resort''s grounds are a notable environmental feature in their own right: more than 3,000 fruit trees are planted across the property, alongside a bird-watching station, an organic farm, and a deer farm — details that set this resort apart from a standard hotel-garden setup and reflect a genuinely working landscape rather than ornamental planting alone.</p><p>The 24-hour, complimentary, roughly five-minute boat transfer to the mainland removes any uncertainty about scheduling; guests can cross to and from the island at any time without needing to plan around fixed departures.</p><h2>Dining</h2><p>The resort operates four restaurants and three bars, confirmed across multiple sources.</p><p>Mezze Restaurant serves authentic Egyptian and Nubian cuisine, the resort''s venue most tied to local and regional flavors. Panorama Restaurant & Bar is positioned at the top of the hotel''s tower, offering 360-degree views and marketed as the highest restaurant in the city, making it a signature dining and sunset-viewing spot given the resort''s island setting. Al Qahwa is a bar and lounge serving drinks and light meals, including cocktails made with fresh fruit, reflecting the resort''s garden and orchard grounds. Orangerie is a glass-fronted restaurant serving light meals, positioned for casual all-day dining.</p><p>This accounts for two confirmed bars (Panorama and Al Qahwa, both restaurant-bar combinations) against a reported total of three bars — a confirmed name for the third bar is not yet available.</p><p>Between Mezze''s Egyptian and Nubian cooking and Panorama''s elevated international dining, the resort has a genuinely varied, confirmed dining lineup shaped directly by its island setting.</p><h2>Why We Chose This Hotel</h2><p>If the Old Cataract represents Aswan''s history, the Mövenpick represents its geography — because no other hotel in this guide is actually surrounded by the Nile on nearly every side. Sitting on the southern tip of Elephantine Island, this resort turns the river itself into part of the daily stay: guests arrive by boat, look out at Aswan''s skyline and the west bank''s granite hills from across the water, and can walk to ancient ruins and Nubian villages without leaving the island their hotel sits on.</p><p>That combination — genuine river-island seclusion, paired with only a few minutes'' boat ride from central Aswan''s museums, souk, and corniche — is difficult to find anywhere else in the city. For travelers who want the drama of an island stay without sacrificing easy access to Aswan itself, the Mövenpick offers something structurally different from every mainland hotel, historic or modern.</p><h2>Nearby Attractions & Activities</h2><p>The hotel''s own island doubles as one of Aswan''s key attractions: Elephantine Island holds ancient ruins including the remains of the Temple of Satet and Khnum, the Nilometer used since antiquity to measure the Nile''s flood levels, and several Nubian villages, all within walking distance of the resort''s grounds. The Aswan Museum, covering the island''s excavated history, sits at the island''s northern end.</p><p>A short boat crossing puts guests in central Aswan, where the Nubian Museum, the Aswan souk, and the corniche are all within easy reach on the mainland side. From the same docks, feluccas and motorboats commonly run to Kitchener''s Island and its botanical gardens, and to the Aga Khan Mausoleum on the west bank — both classic Aswan boat excursions that pair naturally with a stay on Elephantine Island itself.</p><p>Philae Temple, the Aswan High Dam, and the unfinished obelisk are all a short drive from the mainland docks, making them feasible half-day additions once guests cross over from the island. For travelers extending further south, Abu Simbel is reached by a longer road transfer or short flight from Aswan, regardless of which hotel serves as a base.</p><p>Sunset is a particular highlight from this hotel''s position — with unobstructed views over the Nile from an island setting, guests get one of the more dramatic vantage points in Aswan for watching the sun set behind the west bank''s granite hills.</p><h2>Plan Your Stay</h2><p>The Mövenpick Resort Aswan offers something no other hotel on this list can: a stay on an island in the middle of the Nile itself, surrounded by ancient ruins, Nubian villages, and river views in every direction, while remaining only a few minutes by boat from central Aswan. For travelers who want the drama of true river seclusion without sacrificing proximity to the city''s museums and sites, this resort''s Elephantine Island setting is genuinely unique in Aswan. Get in touch with our team to check availability and start planning your stay.</p>',
